   "source": [
    "library(ggplot2)\n",
    "\n",
    "options(repr.plot.width = 15, repr.plot.height = 10)\n",
    "#Plot harga saham\n",
    "temp = data %>% pivot_longer(cols = -date, names_to = \"variable\", values_to = \"value\")\n",
    "ggplot(temp, aes(x = date, y = value))+\n",
    "  geom_line(aes(col = variable))+\n",
    "  labs(title = \"LQ45 Weekly Stock Prices\",\n",
    "       x = \"Period\",\n",
    "       y = \"Price\", color = \"Stock\")+\n",
    "  theme(plot.title = element_text(face=\"bold\"))\n",
    "ggsave(\"output/stock_price.png\",  height = 10, width = 15)"
   ]
  },
