   "source": [
    "library(ggplot2)\n",
    "\n",
    "options(repr.plot.width = 20, repr.plot.height = 10)\n",
    "data1 = data.frame(stock = names(mean0), mean = mean0)\n",
    "data1 = data1[order(data1$mean), ]\n",
    "ggplot(data1, aes(x = reorder(stock, -mean), y = mean)) +\n",
    "  geom_bar(stat = \"identity\", fill = \"skyblue\") +\n",
    "  labs(x = \"Stock\", y = \"Mean Value\", title = \"Mean Value of Stocks\") +\n",
    "  theme(axis.text.x = element_text(angle = 45, hjust = 1))\n",
    "\n",
    "data2 = data.frame(stock = names(sd0), sd = sd0)\n",
    "data2 = data2[order(data2$sd), ]\n",
    "ggplot(data2, aes(x = reorder(stock, -sd), y = sd)) +\n",
    "  geom_bar(stat = \"identity\", fill = \"#FF9999\") +\n",
    "  labs(x = \"Stock\", y = \"Risk Value\", title = \"Risk Value of Stocks\") +\n",
    "  theme(axis.text.x = element_text(angle = 45, hjust = 1))"
   ]
  },
