   "source": [
    "options(repr.plot.width = 10, repr.plot.height = 20)\n",
    "ggplot(data1, aes(x = reorder(stock, -mean), y = mean)) +\n",
    "  geom_bar(stat = \"identity\", fill = \"skyblue\") +\n",
    "  labs(x = \"Stock\", y = \"Mean Value\", title = \"Mean Return LQ45\") +\n",
    "  theme(axis.text.x = element_text(angle = 45, hjust = 1)) +\n",
    "  coord_flip()  \n",
    "ggsave(\"output/mean_ret.png\",  height = 20, width = 8)\n",
    "\n",
    "ggplot(data2, aes(x = reorder(stock, -sd), y = sd)) +\n",
    "  geom_bar(stat = \"identity\", fill = \"#FF9999\") +\n",
    "  labs(x = \"Stock\", y = \"Risk Value\", title = \"Variance of Return LQ45\") +\n",
    "  theme(axis.text.x = element_text(angle = 45, hjust = 1)) +\n",
    "  coord_flip()  \n",
    "ggsave(\"output/var_ret.png\",  height = 20, width = 8)"
   ]
  },
