   "source": [
    "library(forecast)\n",
    "arima_models <- list()\n",
    "\n",
    "for (i in 2:ncol(data)) {\n",
    "  arima_models[[i-1]] <- auto.arima(data[[i]])\n",
    "}\n",
    "\n",
    "options(repr.plot.width = 12.5, repr.plot.height = 10)\n",
    "par(mfrow = c(5, 5))\n",
    "\n",
    "for (i in 1:25){\n",
    "  plot(forecast(arima_models[[i]], h = 1), xlab = stock1[i + 1])\n",
    "}\n",
    "ggsave(\"output/ARIMA1.png\", height = 20, width = 22.5)\n",
    "\n",
    "options(repr.plot.width = 12.5, repr.plot.height = 8)\n",
    "par(mfrow = c(4, 5))\n",
    "\n",
    "for (i in 26:45){\n",
    "  plot(forecast(arima_models[[i]], h = 1), xlab = stock1[i + 1])\n",
    "}\n",
    "ggsave(\"output/ARIMA2.png\", height = 10, width = 20)\n"
   ]
  },
