   "source": [
    "forecast_list <- list()\n",
    "ret <- numeric(length(arima_models))\n",
    "\n",
    "for (i in 1:length(arima_models)) {\n",
    "  forecast_list[[i]] <- forecast(arima_models[[i]], h = 1)[[4]]\n",
    "  ret[i] <- (as.numeric(forecast_list[[i]]) - as.numeric(data[nrow(data), i + 1])) / as.numeric(data[nrow(data), i + 1])\n",
    "}\n",
    "\n",
    "forecast = data.frame(stock = stock1, forecast = as.numeric(forecast_list), return_forecast = ret)\n",
    "forecast = forecast[order(forecast$return_forecast, decreasing = TRUE), ]\n",
    "forecast"
   ]
  },
