   "source": [
    "options(repr.plot.width = 10, repr.plot.height = 20)\n",
    "ggplot(forecast, aes(x = reorder(stock, -return_forecast), y = return_forecast)) +\n",
    "  geom_bar(stat = \"identity\", fill = \"skyblue\") +\n",
    "  labs(x = \"Stock\", y = \"Return Forecast\", title = \"Return Forecast of Stocks\") +\n",
    "  theme(axis.text.x = element_text(angle = 45, hjust = 1)) +\n",
    "  coord_flip()  \n",
    "ggsave(\"output/forecast.png\", height = 20, width = 8)"
   ]
