    "dt1 = data_r[c(\"date\", \"BRPT.JK\", \"MEDC.JK\", \"BBCA.JK\", \"INDF.JK\", \"EMTK.JK\", \"ANTM.JK\")]\n",
    "dt1 = dt1[-1,]\n",
    "\n",
    "s1 = c(\"BRPT\", \"MEDC\", \"BBCA\", \"INDF\", \"EMTK\", \"ANTM\")\n",
    "colnames(dt1) = c(\"date\", s1)\n",
    "dt1"
   ]
