   "source": [
    "options(repr.plot.width = 12, repr.plot.height = 20)\n",
    "\n",
    "ret_long = pivot_longer(dt1, cols = -c(date), values_to = \"Return\", names_to = \"Stock\")\n",
    "\n",
    "gg_plot <- ggplot(ret_long, aes(x = date, y = Return, color = Stock)) +\n",
    "  geom_path() +\n",
    "  facet_grid(Stock ~ .) +\n",
    "  theme_minimal() +\n",
    "  labs(x = \"Date\", y = \"Returns\")\n",
    "gg_plot <- gg_plot + ggtitle(\"Returns of The 6 Selected Stocks\")\n",
    "ggplot\n",
    "# ggsave(\"output/6_return.png\", plot = gg_plot, height = 20, width = 8)"
   ]
  },
