    "unif_sim = function(n_sim = 1000, stock_mean, stock_cov){\n",
    "  set.seed(2023)\n",
    "  rt_p = vector('numeric', length = n_sim)\n",
    "  risk_p = vector('numeric', length = n_sim)\n",
    "  sharpe_p = vector('numeric', length = n_sim)\n",
    "  w_p = matrix(nrow = n_sim, ncol = length(stock_mean))\n",
    "  \n",
    "  for(i in 1:n_sim){\n",
    "    \n",
    "    #Bobot acak uniform\n",
    "    w = runif(length(stock_mean))\n",
    "    w = as.matrix(w/sum(w), nrow = 1)\n",
    "    w_p[i,] = w\n",
    "    \n",
    "    #Return\n",
    "    rt_p[i] = ((sum(w * stock_mean) + 1)^52) - 1\n",
    "    \n",
    "    #Risk\n",
    "    risk_p[i] = sqrt(t(w) %*% (stock_cov %*% w))\n",
    "    \n",
    "    #Sharpe Ratio\n",
    "    sharpe_p[i] = rt_p[i]/risk_p[i]\n",
    "    \n",
    "  }\n",
    "  \n",
    "  results_p = data.frame(\"Returns\" = rt_p,\n",
    "                        \"Risks\" = risk_p,\n",
    "                        \"Sharpe\" = sharpe_p)\n",
    "  w_p = as.data.frame(w_p)\n",
    "  colnames(w_p) = s1\n",
    "  \n",
    "  results_p = cbind(w_p, results_p)\n",
    "  \n",
    "  return(results_p)\n",
    "  \n",
    "}"
   ]
  },
