   "source": [
    "stock_mean = sapply(dt1[-1], function(x) c(mean = mean(x)))\n",
    "stock_mean \n",
    "                    \n",
    "#Covariance Weekly Return\n",
    "stock_cov = cov(dt1[-1])*52\n",
    "stock_cov\n",
    "                    \n",
    "result_sim_1 = unif_sim(n_sim = 500000, stock_mean, stock_cov*52)\n",
    "head(result_sim_1)"
   ]
