   "source": [
    "min_var_1 = result_sim_1[which.min(result_sim_1$Risks),]\n",
    "max_return_1 = result_sim_1[which.max(result_sim_1$Return),]\n",
    "\n",
    "library(ggplot2)\n",
    "library(tidyr)\n",
    "\n",
    "options(repr.plot.width = 10, repr.plot.height = 10)\n",
    "# Maximum Sharpe Ratio\n",
    "max_sharpe_1 = result_sim_1[which.max(result_sim_1$Sharpe),]\n",
    "s = round(max_sharpe_1[1:6], 2) %>%\n",
    "  gather(Stock, Sharpe) %>%\n",
    "  ggplot(aes(x = reorder(Stock, -Sharpe), y = Sharpe, fill = Stock)) +\n",
    "  geom_bar(stat = \"identity\", color = \"black\", alpha = 0.8) +  # Menambahkan tepi hitam pada batang\n",
    "  geom_text(aes(label = Sharpe), vjust = -0.3, size = 3.5, color = \"black\") +  # Warna teks menjadi hitam\n",
    "  scale_fill_brewer(palette = \"Set3\") +  # Ganti palet warna\n",
    "  theme_minimal() +\n",
    "  labs(title = \"Maximum Sharpe Ratio Portfolio\",\n",
    "       subtitle = \"Weekly Data since Oct 2022 - Oct 2023\",\n",
    "       x = \"Stock\", y = \"Weight\") +\n",
    "  theme(axis.text.x = element_text(angle = 45, hjust = 1))  # Rotasi label sumbu x\n",
    "\n",
    "s\n",
    "ggsave(\"output/plot_simulasi.png\", plot = s, height = 8, width = 8)"
   ]
