   "source": [
    "#Plot Semua Kombinasi Weights\n",
    "a = result_sim_1 %>%\n",
    "  ggplot(aes(x = Risks, y = Returns, color = Sharpe))+\n",
    "  geom_point()+\n",
    "  theme_minimal()+\n",
    "  scale_y_continuous(labels = scales::percent)+\n",
    "  scale_x_continuous(labels = scales::percent)+\n",
    "  labs(title = \"Portfolio Optimization using Uniform Simulation\",\n",
    "       subtitle = \"Weekly Data since Oct 2022 - Oct 2023\",\n",
    "       x = \"Risk\",\n",
    "       y = \"Return\")+\n",
    "  geom_point(aes(x = Risks,\n",
    "                 y = Returns), data = min_var_1, color = 'purple')+\n",
    "  geom_point(aes(x = Risks,\n",
    "                 y = Returns), data = max_sharpe_1, color = 'red')+\n",
    "  geom_point(aes(x = Risks,\n",
    "                 y = Returns), data = max_return_1, color = 'black')+\n",
    "  annotate('text', x = max_sharpe_1$Risks, y = max_sharpe_1$Returns-0.025, label = \"Max Sharpe Ratio\")+\n",
    "  annotate('text', x = max_return_1$Risks+0.01, y = max_return_1$Returns-0.025, label = \"Max Returns\")+\n",
    "  annotate('text', x = min_var_1$Risks+0.038, y = min_var_1$Returns-0.025, label = \"Minimum Variance\")\n",
    "a\n",
    "ggsave(\"output/simulasi.png\", a, height = 10, width = 10)"
   ]
  },
