   "source": [
    "s1 = c(\"BRPT.JK\", \"MEDC.JK\", \"BBCA.JK\", \"INDF.JK\", \"EMTK.JK\", \"ANTM.JK\")\n",
    "eval1 = tq_get(s1, from = \"2023-09-28\", to = \"2023-10-7\", get = \"stock.prices\", periodicity = \"daily\")[c(\"symbol\", \"date\", \"close\")]\n",
    "eval1 = pivot_wider(eval1, id_cols = date, names_from = symbol, values_from = close)\n",
    "\n",
    "for(i in 2:ncol(eval1)){\n",
    "    eval1[[i]] = c(NA, diff(eval1[[i]])/eval1[-nrow(eval1),][[i]])\n",
    "}\n",
    "eval1 = eval1[-1,]\n",
    "eval1[\"Return\"] = apply(eval1[, -1], 1, function(x) rowSums(x * max_sharpe_1[1:6]))\n",
    "eval1\n",
    "\n",
    "m1 = mean(eval1$Return)\n",
    "sd1 = sd(eval1$Return)\n",
    "shp1 = m1/sd1\n",
    "m1; sd1; shp1"
   ]
  },
