   "source": [
    "s1 = c(\"BRPT.JK\", \"MEDC.JK\", \"BBCA.JK\", \"INDF.JK\", \"EMTK.JK\", \"ANTM.JK\")\n",
    "dt2 = tq_get(s1, from = \"2022-09-01\", to = \"2023-09-01\", get = \"stock.prices\", periodicity = \"weekly\")[c(\"symbol\", \"date\", \"close\")]\n",
    "dt2 = pivot_wider(dt2, id_cols = date, names_from = symbol, values_from = close)\n",
    "tail(dt2)\n",
    "\n",
    "for(i in 2:ncol(dt2)){\n",
    "    dt2[[i]] = c(NA, diff(dt2[[i]])/dt2[-nrow(dt2),][[i]])\n",
    "}\n",
    "dt2 = dt2[-1,]\n",
    "stock_mean = sapply(dt2[-1], function(x) c(mean = mean(x)))\n",
    "stock_cov = cov(dt2[-1])*52\n",
    "result_sim = unif_sim(n_sim = 500000, stock_mean, stock_cov*52)\n",
    "                    \n",
    "min_var = result_sim[which.min(result_sim$Risks),]\n",
    "max_return = result_sim[which.max(result_sim$Return),]\n",
    "max_sharpe_2 = result_sim[which.max(result_sim$Sharpe),]\n",
    "max_sharpe_2\n",
    "                    \n",
    "eval1 = tq_get(s1, from = \"2023-08-25\", to = \"2023-9-2\", get = \"stock.prices\", periodicity = \"daily\")[c(\"symbol\", \"date\", \"close\")]\n",
    "eval1 = pivot_wider(eval1, id_cols = date, names_from = symbol, values_from = close)\n",
    "\n",
    "for(i in 2:ncol(eval1)){\n",
    "    eval1[[i]] = c(NA, diff(eval1[[i]])/eval1[-nrow(eval1),][[i]])\n",
    "}\n",
    "eval1 = eval1[-1,]\n",
    "eval1[\"Return\"] = apply(eval1[, -1], 1, function(x) rowSums(x * max_sharpe_2[1:6]))\n",
    "eval1\n",
    "m2 = mean(eval1$Return)\n",
    "sd2 = sd(eval1$Return)\n",
    "shp2 = m2/sd2\n",
    "m2; sd2; shp2"
   ]
  },
