   "source": [
    "s1 = c(\"BRPT.JK\", \"MEDC.JK\", \"BBCA.JK\", \"INDF.JK\", \"EMTK.JK\", \"ANTM.JK\")\n",
    "dt3 = tq_get(s1, from = \"2022-08-01\", to = \"2023-08-01\", get = \"stock.prices\", periodicity = \"weekly\")[c(\"symbol\", \"date\", \"close\")]\n",
    "dt3 = pivot_wider(dt3, id_cols = date, names_from = symbol, values_from = close)\n",
    "tail(dt3)\n",
    "\n",
    "for(i in 2:ncol(dt3)){\n",
    "    dt3[[i]] = c(NA, diff(dt3[[i]])/dt3[-nrow(dt3),][[i]])\n",
    "}\n",
    "dt3 = dt3[-1,]\n",
    "stock_mean = sapply(dt3[-1], function(x) c(mean = mean(x)))\n",
    "stock_cov = cov(dt3[-1])*52\n",
    "result_sim = unif_sim(n_sim = 500000, stock_mean, stock_cov*52)\n",
    "                    \n",
    "min_var = result_sim[which.min(result_sim$Risks),]\n",
    "max_return = result_sim[which.max(result_sim$Return),]\n",
    "max_sharpe_3 = result_sim[which.max(result_sim$Sharpe),]\n",
    "max_sharpe_3\n",
    "                    \n",
    "eval1 = tq_get(s1, from = \"2023-07-28\", to = \"2023-8-5\", get = \"stock.prices\", periodicity = \"daily\")[c(\"symbol\", \"date\", \"close\")]\n",
    "eval1 = pivot_wider(eval1, id_cols = date, names_from = symbol, values_from = close)\n",
    "\n",
    "for(i in 2:ncol(eval1)){\n",
    "    eval1[[i]] = c(NA, diff(eval1[[i]])/eval1[-nrow(eval1),][[i]])\n",
    "}\n",
    "eval1 = eval1[-1,]\n",
    "eval1[\"Return\"] = apply(eval1[, -1], 1, function(x) rowSums(x * max_sharpe_3[1:6]))\n",
    "eval1\n",
    "m3 = mean(eval1$Return)\n",
    "sd3 = sd(eval1$Return)\n",
    "shp3 = m3/sd3\n",
    "m3; sd3; shp3"
   ]
  },
