    "s1 = c(\"BRPT.JK\", \"MEDC.JK\", \"BBCA.JK\", \"INDF.JK\", \"EMTK.JK\", \"ANTM.JK\")\n",
    "dt4 = tq_get(s1, from = \"2022-07-01\", to = \"2023-07-01\", get = \"stock.prices\", periodicity = \"weekly\")[c(\"symbol\", \"date\", \"close\")]\n",
    "dt4 = pivot_wider(dt4, id_cols = date, names_from = symbol, values_from = close)\n",
    "tail(dt4)\n",
    "\n",
    "for(i in 2:ncol(dt4)){\n",
    "    dt4[[i]] = c(NA, diff(dt4[[i]])/dt4[-nrow(dt4),][[i]])\n",
    "}\n",
    "dt4 = dt4[-1,]\n",
    "stock_mean = sapply(dt4[-1], function(x) c(mean = mean(x)))\n",
    "stock_cov = cov(dt4[-1])*52\n",
    "result_sim = unif_sim(n_sim = 500000, stock_mean, stock_cov*52)\n",
    "                    \n",
    "min_var = result_sim[which.min(result_sim$Risks),]\n",
    "max_return = result_sim[which.max(result_sim$Return),]\n",
    "max_sharpe_4 = result_sim[which.max(result_sim$Sharpe),]\n",
    "max_sharpe_4\n",
    "                    \n",
    "eval1 = tq_get(s1, from = \"2023-6-26\", to = \"2023-7-6\", get = \"stock.prices\", periodicity = \"daily\")[c(\"symbol\", \"date\", \"close\")]\n",
    "eval1 = pivot_wider(eval1, id_cols = date, names_from = symbol, values_from = close)\n",
    "eval1\n",
    "\n",
    "for(i in 2:ncol(eval1)){\n",
    "    eval1[[i]] = c(NA, diff(eval1[[i]])/eval1[-nrow(eval1),][[i]])\n",
    "}\n",
    "eval1 = eval1[-1,]\n",
    "eval1[\"Return\"] = apply(eval1[, -1], 1, function(x) rowSums(x * max_sharpe_4[1:6]))\n",
    "m4 = mean(eval1$Return)\n",
    "sd4 = sd(eval1$Return)\n",
    "shp4 = m4/sd4\n",
    "m4; sd4; shp4"
   ]
  },
